assert(not game:GetService("RunService"):IsRunning(), "Stop playtesting before installing")
do local parent=game:GetService("ServerScriptService"); local s=parent:FindFirstChild("Grassland"); if s then assert(s.ClassName=="Script") else s=Instance.new("Script"); s.Name="Grassland"; s.Parent=parent end; s.Source="-- Roblox Luau: ServerScriptService > Grassland.\n-- Six fenced grass pens. Slime placement, income, and safe-zone protection come later.\nif workspace:FindFirstChild(\"SlimeMap\") then return end\nlocal map = Instance.new(\"Model\")\nmap.Name = \"SlimeMap\"\nlocal V = Vector3.new\nlocal C = Color3.fromRGB\nlocal palette = {\n    grass = C(102, 180, 72), stone = C(130, 166, 100), trim = C(230, 207, 162),\n    dark = C(78, 100, 53), wood = C(157, 111, 65), path = C(112, 187, 79),\n}\n\n-- One helper handles every anchored building block.\nlocal function part(name, size, position, color, parent, material)\n    local p = Instance.new(\"Part\")\n    p.Name, p.Size, p.Position = name, size, position\n    p.Color = color\n    p.Anchored = true\n    p.Material = material or Enum.Material.SmoothPlastic\n    p.TopSurface, p.BottomSurface = Enum.SurfaceType.Smooth, Enum.SurfaceType.Smooth\n    p.Parent = parent\n    return p\nend\nlocal function model(name, parent)\n    local m = Instance.new(\"Model\")\n    m.Name, m.Parent = name, parent\n    return m\nend\nlocal function sign(text, size, position, color, parent)\n    local board = part(\"Sign\", size, position, color, parent)\n    local gui = Instance.new(\"SurfaceGui\")\n    gui.Face = Enum.NormalId.Back -- Visible while walking north from the plaza.\n    gui.SizingMode = Enum.SurfaceGuiSizingMode.PixelsPerStud\n    gui.PixelsPerStud = 35\n    gui.Parent = board\n    local label = Instance.new(\"TextLabel\")\n    label.Size = UDim2.fromScale(1, 1)\n    label.BackgroundTransparency = 1\n    label.Text = text\n    label.TextColor3 = palette.trim\n    label.Font = Enum.Font.GothamBold\n    label.TextScaled = true\n    label.Parent = gui\n    return board\nend\nlocal function cylinder(name, radius, height, position, color, parent)\n    local p = part(name, V(height, radius * 2, radius * 2), position, color, parent)\n    p.Shape = Enum.PartType.Cylinder\n    p.CFrame = CFrame.new(position) * CFrame.Angles(0, 0, math.rad(90))\n    return p\nend\n-- 1. A narrow corridor joins the wider ranch plaza.\n-- Separate floors remove the unused strips outside the tunnel walls.\npart(\"Grassland\", V(102, 2, 610), V(0, -1, -180), palette.grass, map, Enum.Material.Grass)\npart(\"PlazaGround\", V(192, 2, 130), V(0, -1, 190), palette.grass, map, Enum.Material.Grass)\nlocal walls = model(\"BoundaryWalls\", map)\nfor _, x in ipairs({-96, 96}) do\n    part(\"EdgeWall\", V(4, 40, 130), V(x, 20, 190), palette.stone, walls)\n    part(\"WallCap\", V(5, 1, 130), V(x, 40.5, 190), palette.trim, walls)\n    for z = 135, 255, 40 do\n        part(\"Buttress\", V(6, 42, 6), V(x, 21, z), palette.dark, walls)\n    end\nend\n-- Shoulders close the sides where the plaza meets the corridor.\nfor _, x in ipairs({-73, 73}) do\n    part(\"PlazaShoulder\", V(46, 40, 3), V(x, 20, 125), palette.stone, walls)\n    part(\"ShoulderCap\", V(46, 1, 4), V(x, 40.5, 125), palette.trim, walls)\nend\npart(\"NorthEndWall\", V(102, 40, 4), V(0, 20, -485), palette.stone, walls)\npart(\"NorthEndCap\", V(102, 1, 5), V(0, 40.5, -485), palette.trim, walls)\npart(\"SouthEndWall\", V(192, 40, 4), V(0, 20, 255), palette.stone, walls)\npart(\"SouthEndCap\", V(192, 1, 5), V(0, 40.5, 255), palette.trim, walls)\n\n-- 2. An open-air corridor with tall walls and wall-mounted lights.\npart(\"Plaza\", V(172, 0.2, 122), V(0, 0.1, 190), palette.path, map, Enum.Material.Grass)\nlocal tunnel = model(\"NurseryTunnel\", map)\npart(\"MainPath\", V(22, 0.18, 616), V(0, 0.09, -175), palette.path, tunnel, Enum.Material.Grass)\nfor _, x in ipairs({-12, 12}) do\n    part(\"PathEdging\", V(1, 0.24, 616), V(x, 0.12, -175), C(78, 150, 59), tunnel, Enum.Material.Grass)\nend\nfor _, x in ipairs({-49, 49}) do\n    part(\"TunnelWall\", V(3, 40, 604), V(x, 20, -177), palette.stone, tunnel)\n    part(\"WallBase\", V(4, 2, 604), V(x, 1, -177), palette.dark, tunnel)\n    part(\"CorridorWallCap\", V(4, 1, 604), V(x, 40.5, -177), palette.trim, tunnel)\nend\nfor z = -450, 100, 55 do\n    for _, x in ipairs({-47, 47}) do\n        part(\"WallColumn\", V(4, 42, 5), V(x, 21, z), palette.dark, tunnel)\n        part(\"ColumnFoot\", V(6, 2, 7), V(x, 1, z), palette.trim, tunnel)\n    end\n    for _, x in ipairs({-45, 45}) do\n        local lamp = part(\"WallLight\", V(0.5, 3, 2), V(x, 12, z), C(255, 235, 170), tunnel, Enum.Material.Neon)\n        local light = Instance.new(\"PointLight\")\n        light.Color, light.Brightness, light.Range = C(255, 235, 190), 0.65, 28\n        light.Parent = lamp\n    end\nend\n-- Collection replaces the old overhead entrance sign.\nlocal collectZone = model(\"CollectZone\", map)\nlocal pad = part(\"CollectionPad\", V(95, 0.15, 4), V(0, 0.32, 126), C(158, 219, 166), collectZone)\nfor _, z in ipairs({124.125, 127.875}) do\n    part(\"CollectionBorder\", V(95, 0.2, 0.25), V(0, 0.45, z), C(205, 255, 211), collectZone, Enum.Material.Neon)\nend\nfor _, x in ipairs({-47.375, 47.375}) do\n    part(\"CollectionBorder\", V(0.25, 0.2, 4), V(x, 0.45, 126), C(205, 255, 211), collectZone, Enum.Material.Neon)\nend\nlocal floorGui = Instance.new(\"SurfaceGui\")\nfloorGui.Face, floorGui.SizingMode = Enum.NormalId.Top, Enum.SurfaceGuiSizingMode.PixelsPerStud\nfloorGui.PixelsPerStud, floorGui.Parent = 30, pad\nlocal floorLabel = Instance.new(\"TextLabel\")\nfloorLabel.Size = UDim2.fromScale(1, 1)\nfloorLabel.BackgroundTransparency = 1\nfloorLabel.Text, floorLabel.TextColor3 = \"COLLECT ZONE\", C(37, 81, 51)\nfloorLabel.Font, floorLabel.TextScaled = Enum.Font.GothamBold, true\nfloorLabel.Parent = floorGui\n-- An invisible volume detects the player's position, not the carried body's.\nlocal trigger = part(\"CollectionTrigger\", V(95, 12, 4), V(0, 6, 126), C(255, 255, 255), collectZone)\ntrigger.Transparency, trigger.CanCollide, trigger.CanTouch, trigger.CanQuery = 1, false, false, false\nsign(\"STEAL A SLIME\", V(48, 7, 1), V(0, 16, 248), palette.dark, map)\n\n-- 3. Six open grass pens: three on either side of the center lane.\nlocal bases = model(\"Bases\", map)\nlocal fenceColor = C(175, 126, 74)\nlocal railColor = C(202, 157, 99)\nlocal function fenceRail(position, size, parent)\n    for _, height in ipairs({1.4, 3}) do\n        part(\"FenceRail\", size, position + V(0, height, 0), railColor, parent, Enum.Material.Wood)\n    end\nend\nlocal function fencePost(position, parent)\n    part(\"FencePost\", V(1.2, 4.3, 1.2), position + V(0, 2.15, 0), fenceColor, parent, Enum.Material.Wood)\n    part(\"PostCap\", V(1.5, 0.3, 1.5), position + V(0, 4.45, 0), palette.trim, parent, Enum.Material.Wood)\nend\nfor row, z in ipairs({156, 194, 232}) do\n    for sideIndex, side in ipairs({-1, 1}) do\n        local index = (row - 1) * 2 + sideIndex\n        local x = side * 55\n        local base = model(\"Base\" .. index, bases)\n        base:SetAttribute(\"BaseIndex\", index)\n        base:SetAttribute(\"EntrancePosition\", V(side * 22, 0, z))\n        part(\"PenGrass\", V(66, 0.12, 30), V(x, 0.06, z), C(117, 192, 83), base, Enum.Material.Grass)\n        -- Long fences at the north and south edges of each pen.\n        for _, dz in ipairs({-15, 15}) do\n            fenceRail(V(x, 0, z + dz), V(66, 0.45, 0.6), base)\n            for dx = -33, 33, 11 do\n                fencePost(V(x + dx, 0, z + dz), base)\n            end\n        end\n        -- Back fence and two short front sections leave a 12-stud entrance.\n        local backX, frontX = side * 88, side * 22\n        fenceRail(V(backX, 0, z), V(0.6, 0.45, 30), base)\n        fencePost(V(backX, 0, z), base)\n        for _, dz in ipairs({-10.5, 10.5}) do\n            fenceRail(V(frontX, 0, z + dz), V(0.6, 0.45, 9), base)\n        end\n        fencePost(V(frontX, 0, z - 6), base)\n        fencePost(V(frontX, 0, z + 6), base)\n        local board = sign(\"BASE 0\" .. index, V(8, 2.2, 0.5), V(frontX, 4, z - 10.5), palette.wood, base)\n        board.CFrame = CFrame.new(board.Position) * CFrame.Angles(0, -side * math.pi / 2, 0)\n        -- These are reserved spots; placement and income are later features.\n        local spots = model(\"CollectionSpots\", base)\n        for column, dx in ipairs({-20, 0, 20}) do\n            for spotRow, dz in ipairs({-7, 7}) do\n                local spotIndex = (column - 1) * 2 + spotRow\n                local spot = model(\"Spot\" .. spotIndex, spots)\n                spot:SetAttribute(\"SlotIndex\", spotIndex)\n                spot:SetAttribute(\"Occupied\", false)\n                cylinder(\"SpotBorder\", 3.5, 0.14, V(x + dx, 0.2, z + dz), C(237, 225, 178), spot)\n                cylinder(\"CollectionSpot\", 2.9, 0.1, V(x + dx, 0.32, z + dz), C(155, 213, 110), spot)\n            end\n        end\n    end\nend\n\n-- 4. Nursery bays leave the center lane clear.\nlocal nests = model(\"Nests\", map)\nlocal nurseryPositions = {V(-27, 0, 45), V(27, 0, -65), V(-27, 0, -175), V(27, 0, -285), V(-27, 0, -395)}\nlocal nurseryColors = {C(157, 196, 104), C(114, 184, 196), C(172, 150, 207), C(226, 183, 102), C(214, 137, 131)}\nfor index, center in ipairs(nurseryPositions) do\n    local nest = model(\"Nest\" .. index, nests)\n    nest:SetAttribute(\"SpawnCenter\", center + V(0, 0.7, 0))\n    nest:SetAttribute(\"Zone\", index)\n    local accent = nurseryColors[index]\n    sign(\"ZONE 0\" .. index, V(22, 3, 0.6), V(-35, 12, center.Z + 35), palette.dark, tunnel)\n    part(\"ZoneSignPost\", V(1, 12, 1), V(-35, 6, center.Z + 35), accent, tunnel)\n    cylinder(\"StonePlinth\", 15, 0.5, center + V(0, 0.25, 0), palette.trim, nest)\n    cylinder(\"SoftBed\", 12, 0.2, center + V(0, 0.6, 0), accent, nest)\n    for segment = 0, 31 do\n        local angle = segment * math.pi * 2 / 32\n        local position = center + V(math.cos(angle) * 13, 0.9, math.sin(angle) * 13)\n        local rim = part(\"NestRim\", V(2.8, 0.8, 2.8), position, palette.wood, nest)\n        rim.CFrame = CFrame.new(position) * CFrame.Angles(0, -angle, 0)\n    end\n    for _, dx in ipairs({-11, 11}) do\n        part(\"CanopyPost\", V(1, 9, 1), center + V(dx, 4.5, -9), palette.wood, nest)\n    end\n    part(\"Canopy\", V(28, 1, 8), center + V(0, 9, -10), accent, nest)\n    sign(\"NURSERY 0\" .. index, V(22, 2.5, 0.5), center + V(0, 7, -8), palette.dark, nest)\n    -- A short side path connects each bay to the main walkway.\n    part(\"NurseryApproach\", V(12, 0.15, 7), V(center.X / 2, 0.075, center.Z), palette.path, tunnel, Enum.Material.Grass)\nend\n\n-- The existing spawn is reused so a second spawn is never created.\nlocal spawn = workspace:FindFirstChildWhichIsA(\"SpawnLocation\")\nif spawn then\n    spawn.CFrame = CFrame.new(0, 0.6, 229)\n    spawn.Size = V(10, 1, 10)\n    spawn.Transparency = 1\n    spawn.CanCollide = false\n    spawn.Neutral = true\n    for _, decoration in ipairs(spawn:GetChildren()) do\n        if decoration:IsA(\"Decal\") or decoration:IsA(\"Texture\") then\n            decoration.Transparency = 1\n        end\n    end\nend\nmap:SetAttribute(\"MapVersion\", \"SixGrassPens\")\nmap.Parent = workspace\n" end
do local parent=game:GetService("ServerScriptService"); local s=parent:FindFirstChild("Slimes"); if s then assert(s.ClassName=="Script") else s=Instance.new("Script"); s.Name="Slimes"; s.Parent=parent end; s.Source="-- Put this Script in ServerScriptService alongside Grassland.\n-- Piece 1: one table stores the appearance and fixed rarity of each type.\nlocal types = {\n    {name = \"Grass\", rarity = \"Common\", color = Color3.fromRGB(110, 210, 80)},\n    {name = \"Mud\", rarity = \"Common\", color = Color3.fromRGB(135, 90, 60)},\n    {name = \"Water\", rarity = \"Uncommon\", color = Color3.fromRGB(70, 175, 245)},\n    {name = \"Honey\", rarity = \"Rare\", color = Color3.fromRGB(245, 160, 40)},\n    {name = \"Crystal\", rarity = \"Epic\", color = Color3.fromRGB(175, 115, 245)},\n    {name = \"Gold\", rarity = \"Legendary\", color = Color3.fromRGB(255, 215, 65)},\n}\n\n-- Piece 2: a helper creates one anchored, rounded part.\nlocal function ball(name, size, position, color, parent)\n    local part = Instance.new(\"Part\")\n    part.Name = name\n    part.Shape = Enum.PartType.Ball\n    part.Size = size\n    part.Position = position\n    part.Color = color\n    part.Material = Enum.Material.SmoothPlastic\n    part.Anchored = true\n    part.CanCollide = false\n    part.TopSurface = Enum.SurfaceType.Smooth\n    part.BottomSurface = Enum.SurfaceType.Smooth\n    part.Parent = parent\n    return part\nend\n\n-- Piece 3: wait until Grassland has finished creating the nests.\nlocal map = workspace:WaitForChild(\"SlimeMap\")\nlocal nests = map:WaitForChild(\"Nests\")\nif map:FindFirstChild(\"WildSlimes\") then return end\nlocal slimes = Instance.new(\"Folder\")\nslimes.Name = \"WildSlimes\"\nslimes.Parent = map\n\nfor index, slimeType in ipairs(types) do\n    -- Two types per nest: indices 1/2, 3/4, and 5/6.\n    local nestIndex = math.ceil(index / 2)\n    local nest = nests:WaitForChild(\"Nest\" .. nestIndex)\n    local center = nest:GetAttribute(\"SpawnCenter\") or nest:GetBoundingBox().Position\n    local side = index % 2 == 1 and -4 or 4\n    local position = Vector3.new(center.X + side, center.Y, center.Z)\n\n    local slime = Instance.new(\"Model\")\n    slime.Name = slimeType.name .. \"Slime\"\n    slime:SetAttribute(\"SlimeType\", slimeType.name)\n    slime:SetAttribute(\"Rarity\", slimeType.rarity)\n    slime:SetAttribute(\"NestIndex\", nestIndex)\n    slime.Parent = slimes\n\n    -- The bottom is hidden beneath the ground for a flat-bottomed dome.\n    local body = ball(\"Body\", Vector3.new(4, 3, 4), position + Vector3.new(0, 0.45, 0), slimeType.color, slime)\n    body.Transparency = 0.08\n    slime.PrimaryPart = body\n    local black = Color3.fromRGB(20, 20, 25)\n    ball(\"LeftEye\", Vector3.new(0.28, 0.4, 0.22), position + Vector3.new(-0.65, 1, 1.77), black, slime)\n    ball(\"RightEye\", Vector3.new(0.28, 0.4, 0.22), position + Vector3.new(0.65, 1, 1.77), black, slime)\n    ball(\"Mouth\", Vector3.new(0.4, 0.18, 0.18), position + Vector3.new(0, 0.65, 1.98), black, slime)\nend\nprint(\"Slimes ready: Grass, Mud, Water, Honey, Crystal, Gold\")\n" end
do local parent=game:GetService("ServerScriptService"); local s=parent:FindFirstChild("CombatRules"); if s then assert(s.ClassName=="ModuleScript") else s=Instance.new("ModuleScript"); s.Name="CombatRules"; s.Parent=parent end; s.Source="-- ModuleScript in ServerScriptService. Shared by capture and bat validation.\nlocal Rules = {\n    SwingCooldown = 0.9,\n    HitProtection = 2,\n    StunDuration = 0.55,\n    Range = 8,\n    Knockback = 34,\n    DropLifetime = 30,\n}\nlocal map = workspace:WaitForChild(\"SlimeMap\")\nlocal trigger = map:WaitForChild(\"CollectZone\"):WaitForChild(\"CollectionTrigger\")\nRules.SafeZ = trigger.Position.Z - trigger.Size.Z / 2\nfunction Rules.IsSafe(character)\n    local root = character and character:FindFirstChild(\"HumanoidRootPart\")\n    return root ~= nil and root.Position.Z >= Rules.SafeZ\nend\nfunction Rules.IsStunned(player)\n    return (player:GetAttribute(\"BatStunnedUntil\") or 0) > workspace:GetServerTimeNow()\nend\nreturn Rules\n" end
do local parent=game:GetService("ServerScriptService"); local s=parent:FindFirstChild("Capture"); if s then assert(s.ClassName=="Script") else s=Instance.new("Script"); s.Name="Capture"; s.Parent=parent end; s.Source="-- Roblox Luau: ServerScriptService > Capture.\nlocal Players = game:GetService(\"Players\")\nlocal RunService = game:GetService(\"RunService\")\nlocal StarterPack = game:GetService(\"StarterPack\")\nlocal ServerStorage = game:GetService(\"ServerStorage\")\nlocal CombatRules = require(script.Parent:WaitForChild(\"CombatRules\"))\nlocal secured = Instance.new(\"Folder\")\nsecured.Name, secured.Parent = \"SecuredSlimes\", ServerStorage\nlocal collectionTrigger\nlocal HOLD_SECONDS, REACH = 2, 10\nlocal random = Random.new()\nlocal states, attempts, carrying, messageVersions = {}, {}, {}, {}\n\n-- PIECE 1: build the grabber and give each player clear instructions.\nlocal function piece(name, size, color, parent)\n    local p = Instance.new(\"Part\")\n    p.Name, p.Size, p.Color = name, size, color\n    p.Material = Enum.Material.SmoothPlastic\n    p.CanCollide, p.Massless = false, true\n    p.Parent = parent\n    return p\nend\nlocal tool = Instance.new(\"Tool\")\ntool.Name, tool.CanBeDropped = \"Slime Grabber\", false\nlocal handle = piece(\"Handle\", Vector3.new(1, 1, 2), Color3.fromRGB(65, 106, 94), tool)\nlocal nozzle = piece(\"Nozzle\", Vector3.new(1.4, 1.4, 0.6), Color3.fromRGB(190, 240, 205), tool)\nnozzle.CFrame = handle.CFrame * CFrame.new(0, 0, -1.2)\nlocal joint = Instance.new(\"WeldConstraint\")\njoint.Part0, joint.Part1, joint.Parent = handle, nozzle, handle\nlocal tip = Instance.new(\"Attachment\")\ntip.Name, tip.Position, tip.Parent = \"TetherTip\", Vector3.new(0, 0, -1.6), handle\ntool.Parent = StarterPack\n\nlocal function hint(player, text)\n    local gui = player:FindFirstChild(\"PlayerGui\")\n    gui = gui and gui:FindFirstChild(\"CaptureHint\")\n    if gui then gui.Message.Text = text end\nend\nlocal function defaultHint(player)\n    if carrying[player] then\n        if player:GetAttribute(\"ChasedBy\") then\n            return \"GIANT PARENT CHASING! Reach the green COLLECT ZONE!  |  Q: drop baby\"\n        end\n        return \"Carry this baby to the green COLLECT ZONE to secure it.  |  Q: drop baby\"\n    end\n    return \"Collected: \" .. (player:GetAttribute(\"CollectedSlimes\") or 0) .. \"  |  Equip Slime Grabber [1] and hold E near a baby\"\nend\nlocal function message(player, text)\n    local version = (messageVersions[player] or 0) + 1\n    messageVersions[player] = version\n    hint(player, text)\n    task.delay(4, function()\n        if player.Parent and messageVersions[player] == version then\n            hint(player, defaultHint(player))\n        end\n    end)\nend\nlocal function setupCharacter(player, character)\n    local backpack = player:WaitForChild(\"Backpack\")\n    if not backpack:FindFirstChild(tool.Name) and not character:FindFirstChild(tool.Name) then\n        tool:Clone().Parent = backpack\n    end\n    local playerGui = player:WaitForChild(\"PlayerGui\")\n    if not playerGui:FindFirstChild(\"CaptureHint\") then\n        local gui = Instance.new(\"ScreenGui\")\n        gui.Name, gui.ResetOnSpawn = \"CaptureHint\", false\n        local label = Instance.new(\"TextLabel\")\n        label.Name = \"Message\"\n        label.AnchorPoint = Vector2.new(0.5, 1)\n        label.Position, label.Size = UDim2.new(0.5, 0, 1, -85), UDim2.new(0.8, 0, 0, 54)\n        label.BackgroundColor3 = Color3.fromRGB(35, 55, 46)\n        label.BackgroundTransparency = 0.15\n        label.TextColor3 = Color3.fromRGB(245, 240, 220)\n        label.Font, label.TextSize, label.TextWrapped = Enum.Font.GothamMedium, 17, true\n        label.Parent, gui.Parent = gui, playerGui\n    end\n    hint(player, defaultHint(player))\nend\n\n-- PIECE 2: the server checks equipment, range, timing, power, and ownership.\n-- Weights live only in this server table, never as visible model attributes.\nlocal function power(player)\n    local value = player:GetAttribute(\"GrabberPower\")\n    if type(value) ~= \"number\" or value ~= value then return 10 end\n    return math.clamp(value, 0, 1000000)\nend\nlocal function eligible(player, state)\n    local character = player.Character\n    local root = character and character:FindFirstChild(\"HumanoidRootPart\")\n    local humanoid = character and character:FindFirstChildOfClass(\"Humanoid\")\n    local equipped = character and character:FindFirstChild(\"Slime Grabber\")\n    if not root or not humanoid or humanoid.Health <= 0 then return false end\n    if not equipped or not equipped:IsA(\"Tool\") then return false end\n    if CombatRules.IsStunned(player) then return false end\n    if carrying[player] or state.slime:GetAttribute(\"Captured\") then return false end\n    if state.owner and state.owner ~= player then return false end\n    if not state.slime.PrimaryPart or not state.slime:IsDescendantOf(workspace) then return false end\n    if (root.Position - state.slime.PrimaryPart.Position).Magnitude > REACH then return false end\n    local params = RaycastParams.new()\n    params.FilterType = Enum.RaycastFilterType.Exclude\n    -- Avatars and cosmetic accessories must not block collecting a nearby baby.\n    local exclusions = {state.slime}\n    for _, other in ipairs(Players:GetPlayers()) do\n        if other.Character then table.insert(exclusions, other.Character) end\n    end\n    params.FilterDescendantsInstances = exclusions\n    local origin = root.Position + Vector3.new(0, 1, 0)\n    if workspace:Raycast(origin, state.slime.PrimaryPart.Position - origin, params) then return false end\n    return true, root, humanoid, equipped\nend\nlocal function cancel(player)\n    local state = attempts[player]\n    if not state then return end\n    attempts[player] = nil\n    state.owner, state.started, state.released = nil, nil, nil\n    if state.beam then state.beam:Destroy(); state.beam = nil end\nend\nlocal function begin(player, state)\n    if not eligible(player, state) then\n        message(player, \"Equip your grabber, move closer, and carry only one baby at a time.\")\n        return\n    end\n    cancel(player)\n    state.weight = state.weight or random:NextInteger(1, 20)\n    if state.weight > power(player) then\n        message(player, \"This baby needs more Grabber Power. Try another slime.\")\n        return\n    end\n    local _, _, _, equipped = eligible(player, state)\n    state.owner, state.started, state.released = player, os.clock(), nil\n    attempts[player] = state\n    local beam = Instance.new(\"Beam\")\n    beam.Attachment0 = equipped.Handle.TetherTip\n    beam.Attachment1 = state.attachment\n    beam.Width0, beam.Width1, beam.FaceCamera = 0.15, 0.1, true\n    beam.Color = ColorSequence.new(Color3.fromRGB(190, 245, 205))\n    beam.Parent, state.beam = state.slime.PrimaryPart, beam\n    message(player, \"Keep holding E to pull this baby free...\")\nend\n\n-- PIECE 3: weld a successful capture to the character and apply slowdown.\n-- Future chase code can listen to this server-only event.\nlocal captured = Instance.new(\"BindableEvent\")\ncaptured.Name, captured.Parent = \"SlimeCaptured\", script\nlocal released = Instance.new(\"BindableEvent\")\nreleased.Name, released.Parent = \"SlimeReleased\", script\nlocal function release(player, dropFrame)\n    cancel(player)\n    local record = carrying[player]\n    if not record then return end\n    carrying[player] = nil\n    for _, weld in ipairs(record.welds) do weld:Destroy() end\n    for _, p in ipairs(record.state.slime:GetDescendants()) do\n        if p:IsA(\"BasePart\") then p.Anchored = true end\n    end\n    local state = record.state\n    state.dropVersion = (state.dropVersion or 0) + 1\n    state.dropped = dropFrame ~= nil\n    state.dropExpires = state.dropped and (os.clock() + CombatRules.DropLifetime) or nil\n    state.prompt.HoldDuration = state.dropped and 0 or HOLD_SECONDS\n    state.prompt.ActionText = state.dropped and \"Pick up dropped baby\" or \"Pull with grabber\"\n    record.state.slime:PivotTo(dropFrame or record.state.home)\n    record.state.slime:SetAttribute(\"Captured\", false)\n    record.state.slime:SetAttribute(\"CarrierUserId\", nil)\n    record.state.prompt.Enabled = true\n    if record.humanoid.Parent then record.humanoid.WalkSpeed = record.speed end\n    player:SetAttribute(\"CarryingSlime\", nil)\n    released:Fire(player, record.state.slime)\nend\nlocal caught = Instance.new(\"BindableEvent\")\ncaught.Name, caught.Parent = \"ParentCaught\", script\ncaught.Event:Connect(function(player, slime)\n    local record = carrying[player]\n    if record and record.state.slime == slime then\n        release(player)\n        message(player, \"The parent caught you! The baby returned to its nursery.\")\n    end\nend)\nlocal function finish(player, state)\n    if state.dropped then\n        if state.dropExpires and os.clock() >= state.dropExpires then return end\n    else\n        if attempts[player] ~= state or state.owner ~= player then return end\n        local elapsed = (state.released or os.clock()) - state.started\n        if elapsed < HOLD_SECONDS - 0.1 then cancel(player); return end\n    end\n    local valid, root, humanoid = eligible(player, state)\n\n    if not valid or state.weight > power(player) then cancel(player); return end\n    cancel(player)\n    local slime, body = state.slime, state.slime.PrimaryPart\n    state.dropped, state.dropExpires = false, nil\n    state.dropVersion = (state.dropVersion or 0) + 1\n    state.prompt.HoldDuration, state.prompt.ActionText = HOLD_SECONDS, \"Pull with grabber\"\n    state.prompt.Enabled = false\n    slime:SetAttribute(\"Captured\", true)\n    slime:SetAttribute(\"CarrierUserId\", player.UserId)\n    player:SetAttribute(\"CarryingSlime\", slime.Name)\n    slime:PivotTo(root.CFrame * CFrame.new(2.5, 1, -3))\n    local welds = {}\n    for _, p in ipairs(slime:GetDescendants()) do\n        if p:IsA(\"BasePart\") then\n            p.Anchored, p.CanCollide, p.Massless = false, false, true\n            if p ~= body then\n                local weld = Instance.new(\"WeldConstraint\")\n                weld.Part0, weld.Part1, weld.Parent = body, p, body\n                table.insert(welds, weld)\n            end\n        end\n    end\n    local grip = Instance.new(\"WeldConstraint\")\n    grip.Part0, grip.Part1, grip.Parent = root, body, body\n    table.insert(welds, grip)\n    local speed = humanoid.WalkSpeed\n    carrying[player] = {state = state, humanoid = humanoid, speed = speed, welds = welds}\n    humanoid.WalkSpeed = math.max(6, speed * (1 - 0.35 * state.weight / math.max(1, power(player))))\n    message(player, \"Captured \" .. slime:GetAttribute(\"SlimeType\") .. \"! Run to the COLLECT ZONE before its parent catches you.\")\n    captured:Fire(player, slime, state.weight)\nend\n\n-- Collection stores secured babies privately for this session.\n-- The later inventory feature can read these models and their hidden weights.\nlocal slimeSecured = Instance.new(\"BindableEvent\")\nslimeSecured.Name, slimeSecured.Parent = \"SlimeSecured\", script\nlocal function collect(player, record)\n    local character = player.Character\n    local root = character and character:FindFirstChild(\"HumanoidRootPart\")\n    if not root or record.humanoid.Health <= 0 or not collectionTrigger then return end\n    local position = collectionTrigger.CFrame:PointToObjectSpace(root.Position)\n    local half = collectionTrigger.Size / 2\n    if math.abs(position.X) > half.X or math.abs(position.Y) > half.Y or math.abs(position.Z) > half.Z then return end\n    local folder = secured:FindFirstChild(tostring(player.UserId))\n    if not folder then return end\n    -- Clear carrying first, so repeated frames cannot award the same baby twice.\n    carrying[player] = nil\n    for _, weld in ipairs(record.welds) do weld:Destroy() end\n    local slime = record.state.slime\n    for _, item in ipairs(slime:GetDescendants()) do\n        if item:IsA(\"BasePart\") then item.Anchored = true end\n    end\n    slime.Parent = folder -- ServerStorage does not replicate to players.\n    slime:SetAttribute(\"Weight\", record.state.weight)\n    slime:SetAttribute(\"Secured\", true)\n    slime:SetAttribute(\"CarrierUserId\", nil)\n    record.humanoid.WalkSpeed = record.speed\n    player:SetAttribute(\"CarryingSlime\", nil)\n    player:SetAttribute(\"CollectedSlimes\", #folder:GetChildren())\n    states[slime] = nil\n    message(player, \"Secured \" .. slime:GetAttribute(\"SlimeType\") .. \" baby! Collected: \" .. #folder:GetChildren())\n    slimeSecured:Fire(player, slime, record.state.weight)\nend\n\nlocal function setupPlayer(player)\n    local folder = Instance.new(\"Folder\")\n    folder.Name, folder.Parent = tostring(player.UserId), secured\n    player:SetAttribute(\"CollectedSlimes\", 0)\n    if player:GetAttribute(\"GrabberPower\") == nil then player:SetAttribute(\"GrabberPower\", 10) end\n    player.CharacterRemoving:Connect(function() release(player) end)\n    player.CharacterAdded:Connect(function(character)\n        setupCharacter(player, character)\n        local humanoid = character:WaitForChild(\"Humanoid\")\n        humanoid.Died:Connect(function() release(player) end)\n    end)\n    if player.Character then\n        local character = player.Character\n        task.spawn(function()\n            setupCharacter(player, character)\n            character:WaitForChild(\"Humanoid\").Died:Connect(function() release(player) end)\n        end)\n    end\nend\nPlayers.PlayerAdded:Connect(setupPlayer)\nPlayers.PlayerRemoving:Connect(function(player)\n    release(player)\n    messageVersions[player] = nil\n    local folder = secured:FindFirstChild(tostring(player.UserId))\n    if folder then folder:Destroy() end\nend)\nfor _, player in ipairs(Players:GetPlayers()) do setupPlayer(player) end\n\nRunService.Heartbeat:Connect(function()\n    for player, state in pairs(attempts) do\n        if not eligible(player, state) or (state.released and os.clock() - state.released > 0.2) then\n            cancel(player)\n        end\n    end\n    for player, record in pairs(carrying) do collect(player, record) end\n    local now = os.clock()\n    for _, state in pairs(states) do\n        if state.dropped and state.dropExpires and now >= state.dropExpires then\n            cancel(state.owner)\n            state.dropped, state.dropExpires = false, nil\n            state.prompt.Enabled = true\n            state.prompt.HoldDuration, state.prompt.ActionText = HOLD_SECONDS, \"Pull with grabber\"\n            state.slime:PivotTo(state.home)\n        end\n    end\nend)\nlocal slimes = workspace:WaitForChild(\"SlimeMap\"):WaitForChild(\"WildSlimes\")\ncollectionTrigger = slimes.Parent:WaitForChild(\"CollectZone\"):WaitForChild(\"CollectionTrigger\")\nlocal function register(slime)\n    if not slime:IsA(\"Model\") or states[slime] then return end\n    slime:WaitForChild(\"Mouth\") -- The spawner creates the mouth last.\n    local body = slime.PrimaryPart\n    if not body then return end\n    local attachment = Instance.new(\"Attachment\")\n    attachment.Parent = body\n    local prompt = Instance.new(\"ProximityPrompt\")\n    prompt.Name, prompt.ObjectText, prompt.ActionText = \"CapturePrompt\", slime:GetAttribute(\"SlimeType\") .. \" baby\", \"Pull with grabber\"\n    prompt.HoldDuration, prompt.MaxActivationDistance = HOLD_SECONDS, REACH\n    prompt.RequiresLineOfSight = false -- The server checks the actual path.\n    prompt.Parent = body\n    local state = {slime = slime, prompt = prompt, attachment = attachment, home = slime:GetPivot()}\n    states[slime] = state\n    prompt.PromptButtonHoldBegan:Connect(function(player)\n        if not state.dropped then begin(player, state) end\n    end)\n    prompt.PromptButtonHoldEnded:Connect(function(player)\n        if attempts[player] == state then state.released = os.clock() end\n    end)\n    prompt.Triggered:Connect(function(player) finish(player, state) end)\nend\nslimes.ChildAdded:Connect(function(slime) task.spawn(register, slime) end)\nfor _, slime in ipairs(slimes:GetChildren()) do task.spawn(register, slime) end\nprint(\"Capture ready: equip Slime Grabber, then hold E near a baby.\")\n\n\n-- Only server scripts can invoke this function. It atomically releases capture ownership.\nlocal interrupt = Instance.new(\"BindableFunction\")\ninterrupt.Name = \"InterruptForBat\"\ninterrupt.OnInvoke = function(player)\n    cancel(player)\n    local record = carrying[player]\n    if not record then return false end\n    local character = player.Character\n    local root = character and character:FindFirstChild(\"HumanoidRootPart\")\n    if not root then release(player); return false end\n    local position = Vector3.new(math.clamp(root.Position.X, -38, 38), root.Position.Y, math.min(root.Position.Z, CombatRules.SafeZ - 4))\n    local params = RaycastParams.new()\n    params.FilterType = Enum.RaycastFilterType.Exclude\n    local exclusions = {record.state.slime}\n    for _, other in ipairs(Players:GetPlayers()) do\n        if other.Character then table.insert(exclusions, other.Character) end\n    end\n    local map = workspace:FindFirstChild(\"SlimeMap\")\n    if map then\n        if map:FindFirstChild(\"WildSlimes\") then table.insert(exclusions, map.WildSlimes) end\n        if map:FindFirstChild(\"Guardians\") then table.insert(exclusions, map.Guardians) end\n    end\n    params.FilterDescendantsInstances = exclusions\n    local ground = workspace:Raycast(position + Vector3.new(0, 4, 0), Vector3.new(0, -100, 0), params)\n    local dropFrame\n    if ground then\n        local height = record.state.slime.PrimaryPart.Size.Y * 0.5 + 0.1\n        dropFrame = CFrame.new(ground.Position + Vector3.new(0, height, 0)) * record.state.home.Rotation\n    end\n    release(player, dropFrame)\n    message(player, dropFrame and \"You dropped your baby! Equip your grabber and pick it back up.\" or \"Your baby returned to its nursery.\")\n    return dropFrame ~= nil\nend\ninterrupt.Parent = script\n" end
do local parent=game:GetService("ServerScriptService"); local s=parent:FindFirstChild("Guardians"); if s then assert(s.ClassName=="Script") else s=Instance.new("Script"); s.Name="Guardians"; s.Parent=parent end; s.Source="-- Roblox Luau: ServerScriptService > Guardians.\nlocal Players = game:GetService(\"Players\")\nlocal RunService = game:GetService(\"RunService\")\nlocal PathfindingService = game:GetService(\"PathfindingService\")\nlocal capture = script.Parent:WaitForChild(\"Capture\")\nlocal captured = capture:WaitForChild(\"SlimeCaptured\")\nlocal secured = capture:WaitForChild(\"SlimeSecured\")\nlocal released = capture:WaitForChild(\"SlimeReleased\")\nlocal caught = capture:WaitForChild(\"ParentCaught\")\nlocal map = workspace:WaitForChild(\"SlimeMap\")\nlocal slimes = map:WaitForChild(\"WildSlimes\")\nlocal trigger = map:WaitForChild(\"CollectZone\"):WaitForChild(\"CollectionTrigger\")\nlocal safeZ = trigger.Position.Z - trigger.Size.Z / 2\nlocal SPEED, GRACE, CATCH_DISTANCE = 14, 1.5, 6\nlocal V = Vector3.new\nlocal records = {}\nlocal parents = Instance.new(\"Folder\")\nparents.Name, parents.Parent = \"Guardians\", map\n\n-- PIECE 1: build a large parent with the baby's color and angry eyebrows.\nlocal function part(name, size, color, frame, parent, ball)\n    local p = Instance.new(\"Part\")\n    p.Name, p.Size, p.Color, p.CFrame = name, size, color, frame\n    p.Anchored, p.CanCollide, p.CanTouch, p.CanQuery = true, false, false, false\n    p.Material = Enum.Material.SmoothPlastic\n    if ball then p.Shape = Enum.PartType.Ball end\n    p.Parent = parent\n    return p\nend\nlocal function register(slime)\n    if records[slime] then return records[slime] end\n    if not slime:IsA(\"Model\") then return end\n    slime:WaitForChild(\"Mouth\")\n    local body = slime.PrimaryPart\n    if not body then return end\n    local nest = map.Nests:FindFirstChild(\"Nest\" .. tostring(slime:GetAttribute(\"NestIndex\")))\n    if not nest then return end\n    local center = nest:GetAttribute(\"SpawnCenter\")\n    local side = body.Position.X < center.X and -1 or 1\n    local home = V(center.X + side * 9, 0, center.Z - 24)\n    local model = Instance.new(\"Model\")\n    model.Name = slime:GetAttribute(\"SlimeType\") .. \"Parent\"\n    model:SetAttribute(\"SlimeType\", slime:GetAttribute(\"SlimeType\"))\n    model:SetAttribute(\"State\", \"Idle\")\n    local root = part(\"Root\", V(1, 1, 1), body.Color, CFrame.new(home), model)\n    root.Transparency = 1\n    model.PrimaryPart = root\n    local skin = part(\"Body\", V(14, 12, 14), body.Color, CFrame.new(home + V(0, 4.2, 0)), model, true)\n    skin.Transparency = 0.06\n    local black = Color3.fromRGB(25, 30, 24)\n    for _, x in ipairs({-2.3, 2.3}) do\n        part(\"Eye\", V(0.9, 1.2, 0.45), black, CFrame.new(home + V(x, 5.5, -6.3)), model, true)\n        part(\"AngryBrow\", V(2.5, 0.5, 0.45), black,\n            CFrame.new(home + V(x, 6.5, -6)) * CFrame.Angles(0, 0, math.rad(x < 0 and -25 or 25)), model)\n    end\n    part(\"Mouth\", V(2.3, 0.55, 0.4), black, CFrame.new(home + V(0, 3.6, -6.9)), model, true)\n    model.Parent = parents\n    local record = {\n        slime = slime, model = model, home = home, position = home,\n        rotation = CFrame.Angles(0, math.pi, 0), phase = 0,\n        revision = 0, nextPath = 0, waypoints = {}, waypoint = 1,\n    }\n    records[slime] = record\n    model:PivotTo(CFrame.new(home) * record.rotation)\n    return record\nend\n\n-- PIECE 2: capture starts a chase; collection, release, or leaving ends it.\nlocal function stop(record)\n    local player = record.target\n    if player and player:GetAttribute(\"ChasedBy\") == record.model.Name then\n        player:SetAttribute(\"ChasedBy\", nil)\n    end\n    record.target, record.character = nil, nil\n    record.revision = record.revision + 1\n    record.waypoints, record.waypoint, record.nextPath = {}, 1, 0\n    record.model:SetAttribute(\"State\", \"Returning\")\n    record.model:SetAttribute(\"TargetUserId\", nil)\nend\ncaptured.Event:Connect(function(player, slime)\n    local record = records[slime] or register(slime)\n    if not record then return end\n    if record.target then stop(record) end\n    record.target, record.character = player, player.Character\n    record.wakeAt = os.clock() + GRACE\n    record.revision = record.revision + 1\n    record.waypoints, record.waypoint, record.nextPath = {}, 1, 0\n    record.model:SetAttribute(\"State\", \"Chasing\")\n    record.model:SetAttribute(\"TargetUserId\", player.UserId)\n    player:SetAttribute(\"ChasedBy\", record.model.Name)\nend)\nlocal function endChase(_, slime)\n    local record = records[slime]\n    if record then stop(record) end\nend\nsecured.Event:Connect(endChase)\nreleased.Event:Connect(endChase)\nPlayers.PlayerRemoving:Connect(function(player)\n    for _, record in pairs(records) do\n        if record.target == player then stop(record) end\n    end\nend)\n\n-- PIECE 3: request paths without blocking the frame update.\n-- A revision number prevents an old path from replacing a newer chase.\nlocal obstacles = RaycastParams.new()\nobstacles.FilterType = Enum.RaycastFilterType.Include\nobstacles.FilterDescendantsInstances = {map.NurseryTunnel, map.Nests, map.BoundaryWalls}\nlocal function clearStep(position, delta)\n    for _, height in ipairs({3, 9}) do\n        if workspace:Raycast(position + V(0, height, 0), delta, obstacles) then return false end\n    end\n    return true\nend\nlocal function requestPath(record, goal, now)\n    if record.pathBusy or now < record.nextPath then return end\n    record.pathBusy, record.nextPath = true, now + 1\n    local revision, start = record.revision, record.position\n    task.spawn(function()\n        local path = PathfindingService:CreatePath({AgentRadius = 7, AgentHeight = 11, AgentCanJump = false, WaypointSpacing = 5})\n        local ok = pcall(function() path:ComputeAsync(start + V(0, 2, 0), goal + V(0, 2, 0)) end)\n        record.pathBusy = false\n        if record.revision ~= revision then return end\n        if ok and path.Status == Enum.PathStatus.Success then\n            local waypoints = path:GetWaypoints()\n            local leavesCorridor = false\n            for _, waypoint in ipairs(waypoints) do\n                if math.abs(waypoint.Position.X) > 40 or waypoint.Position.Z > safeZ - 7 then\n                    leavesCorridor = true\n                    break\n                end\n            end\n            -- The wide center lane gives large parents room around nursery roofs.\n            if leavesCorridor then\n                record.waypoints, record.waypoint = {{Position = V(0, 0, start.Z)}}, 1\n            else\n                record.waypoints, record.waypoint = waypoints, 2\n            end\n        else\n            record.waypoints, record.waypoint = {}, 1\n        end\n    end)\nend\nlocal function tick(record, dt, now)\n    local goal\n    if record.target then\n        local player, character = record.target, record.character\n        local root = character and character:FindFirstChild(\"HumanoidRootPart\")\n        local humanoid = character and character:FindFirstChildOfClass(\"Humanoid\")\n        if not player.Parent or player.Character ~= character or not root or not humanoid or humanoid.Health <= 0\n            or player:GetAttribute(\"CarryingSlime\") ~= record.slime.Name or root.Position.Z >= safeZ then\n            stop(record)\n        elseif now >= record.wakeAt then\n            local delta = root.Position - record.position\n            local horizontal = V(delta.X, 0, delta.Z)\n            if horizontal.Magnitude <= CATCH_DISTANCE and math.abs(delta.Y) < 12 then\n                -- Check the line of sight before catching through an obstacle.\n                local params = RaycastParams.new()\n                params.FilterType = Enum.RaycastFilterType.Exclude\n                params.FilterDescendantsInstances = {character, parents, record.slime}\n                if not workspace:Raycast(record.position + V(0, 4, 0), root.Position - (record.position + V(0, 4, 0)), params) then\n                    caught:Fire(player, record.slime)\n                    stop(record)\n                else\n                    goal = V(math.clamp(root.Position.X, -39, 39), 0, math.min(root.Position.Z, safeZ - 7))\n                end\n            else\n                goal = V(math.clamp(root.Position.X, -39, 39), 0, math.min(root.Position.Z, safeZ - 7))\n            end\n        end\n    end\n    if not record.target and record.model:GetAttribute(\"State\") == \"Returning\" then\n        if (record.position - record.home).Magnitude < 1.1 then\n            record.position = record.home\n            record.model:SetAttribute(\"State\", \"Idle\")\n        else\n            goal = record.home\n        end\n    end\n    local moved = false\n    if goal then\n        requestPath(record, goal, now)\n        local waypoint = record.waypoints[record.waypoint]\n        local destination = waypoint and V(waypoint.Position.X, 0, waypoint.Position.Z) or goal\n        local delta = destination - record.position\n        if delta.Magnitude < 1 then\n            record.waypoint = record.waypoint + 1\n        else\n            local step = delta.Unit * math.min(delta.Magnitude, SPEED * math.min(dt, 0.1))\n            local nextPosition = record.position + step\n            if nextPosition.Z <= safeZ - 7 and math.abs(nextPosition.X) <= 40 and clearStep(record.position, step) then\n                record.position = nextPosition\n                record.rotation = record.rotation:Lerp(CFrame.lookAt(V(0, 0, 0), delta.Unit), math.min(1, dt * 8))\n                moved = true\n            else\n                record.nextPath = 0\n            end\n        end\n    end\n    record.phase = record.phase + dt * (moved and 8 or 2)\n    local bounce = math.abs(math.sin(record.phase)) * (moved and 0.7 or 0.08)\n    record.model:PivotTo(CFrame.new(record.position + V(0, bounce, 0)) * record.rotation)\nend\nslimes.ChildAdded:Connect(function(slime) task.spawn(register, slime) end)\nfor _, slime in ipairs(slimes:GetChildren()) do task.spawn(register, slime) end\nRunService.Heartbeat:Connect(function(dt)\n    local now = os.clock()\n    for _, record in pairs(records) do tick(record, dt, now) end\nend)\nprint(\"Guardians ready: giant parents chase captured babies and stop at the collect zone.\")\n" end
do local parent=game:GetService("ServerScriptService"); local s=parent:FindFirstChild("Bat"); if s then assert(s.ClassName=="Script") else s=Instance.new("Script"); s.Name="Bat"; s.Parent=parent end; s.Source="-- Slime Bat: clients request swings; the server decides range, safety and the hit.\nlocal Players = game:GetService(\"Players\")\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal StarterPack = game:GetService(\"StarterPack\")\nlocal TweenService = game:GetService(\"TweenService\")\nlocal Debris = game:GetService(\"Debris\")\nlocal Rules = require(script.Parent:WaitForChild(\"CombatRules\"))\nlocal interrupt = script.Parent:WaitForChild(\"Capture\"):WaitForChild(\"InterruptForBat\")\nlocal remote = Instance.new(\"RemoteEvent\")\nremote.Name, remote.Parent = \"SlimeBatSwing\", ReplicatedStorage\nlocal lastSwing, stuns = {}, {}\nlocal tool = Instance.new(\"Tool\")\ntool.Name, tool.CanBeDropped = \"Slime Bat\", false\ntool.ToolTip = \"Knock back a rival and drop their baby. Bases are safe.\"\ntool.Grip = CFrame.new(0, -0.8, 0)\nlocal function part(name, size, offset, color)\n    local p = Instance.new(\"Part\")\n    p.Name, p.Size, p.CFrame, p.Color = name, size, CFrame.new(offset), color\n    p.Material, p.CanCollide, p.CanTouch, p.Massless = Enum.Material.SmoothPlastic, false, false, true\n    p.Parent = tool\n    return p\nend\nlocal handle = part(\"Handle\", Vector3.new(.38, 1.4, .38), Vector3.zero, Color3.fromRGB(62,69,89))\nlocal barrel = part(\"PaddedHead\", Vector3.new(1.1, 3, 1.1), Vector3.new(0, 2, 0), Color3.fromRGB(70,218,255))\nlocal cap = part(\"EndCap\", Vector3.new(1.15,.22,1.15), Vector3.new(0,3.55,0), Color3.fromRGB(166,255,49))\nfor _, p in ipairs({barrel, cap}) do\n    local weld = Instance.new(\"WeldConstraint\")\n    weld.Part0, weld.Part1, weld.Parent = handle, p, handle\nend\ntool.Parent = StarterPack\nlocal function getLiving(player)\n    local character = player.Character\n    local root = character and character:FindFirstChild(\"HumanoidRootPart\")\n    local hum = character and character:FindFirstChildOfClass(\"Humanoid\")\n    if root and hum and hum.Health > 0 then return character, root, hum end\nend\nlocal function feedback(player, text)\n    remote:FireClient(player, \"Message\", text)\nend\nlocal function animate(bat)\n    local rest = CFrame.new(0, -.8, 0)\n    local forward = TweenService:Create(bat, TweenInfo.new(.10), {Grip = rest * CFrame.Angles(0, 0, math.rad(-95))})\n    forward:Play()\n    task.delay(.12, function()\n        if bat.Parent then TweenService:Create(bat, TweenInfo.new(.16), {Grip = rest}):Play() end\n    end)\nend\nlocal function knockback(player, root, humanoid, attackerRoot)\n    local now = workspace:GetServerTimeNow()\n    player:SetAttribute(\"BatProtectedUntil\", now + Rules.HitProtection)\n    player:SetAttribute(\"BatStunnedUntil\", now + Rules.StunDuration)\n    local record = {humanoid = humanoid, speed = humanoid.WalkSpeed, rotate = humanoid.AutoRotate}\n    stuns[player] = record\n    humanoid.WalkSpeed, humanoid.AutoRotate = 0, false\n    local delta = root.Position - attackerRoot.Position\n    local flat = Vector3.new(delta.X, 0, delta.Z)\n    local direction = flat.Magnitude > .01 and flat.Unit or attackerRoot.CFrame.LookVector\n    -- Server owns the short impact, so a client cannot suppress it.\n    local canOwn = root:CanSetNetworkOwnership()\n    if canOwn then root:SetNetworkOwner(nil) end\n    root:ApplyImpulse((direction * Rules.Knockback + Vector3.new(0,12,0)) * root.AssemblyMass)\n    local glow = Instance.new(\"Highlight\")\n    glow.Name, glow.Adornee = \"BatProtection\", player.Character\n    glow.FillColor, glow.OutlineColor = Color3.fromRGB(132,239,255), Color3.new(1,1,1)\n    glow.FillTransparency, glow.OutlineTransparency = .8, .25\n    glow.Parent = player.Character\n    Debris:AddItem(glow, Rules.HitProtection)\n    task.delay(Rules.StunDuration, function()\n        if stuns[player] ~= record then return end\n        stuns[player] = nil\n        if humanoid.Parent and humanoid.Health > 0 then\n            humanoid.WalkSpeed, humanoid.AutoRotate = record.speed, record.rotate\n        end\n        if root.Parent and canOwn then root:SetNetworkOwnershipAuto() end\n    end)\nend\nlocal function clearLine(a, b, attacker, target)\n    local params = RaycastParams.new()\n    params.FilterType = Enum.RaycastFilterType.Exclude\n    local excluded = {attacker, target}\n    for _, p in ipairs(Players:GetPlayers()) do\n        if p.Character then table.insert(excluded, p.Character) end\n    end\n    local map = workspace:FindFirstChild(\"SlimeMap\")\n    if map then\n        if map:FindFirstChild(\"WildSlimes\") then table.insert(excluded, map.WildSlimes) end\n        if map:FindFirstChild(\"Guardians\") then table.insert(excluded, map.Guardians) end\n    end\n    params.FilterDescendantsInstances = excluded\n    return not workspace:Raycast(a, b - a, params)\nend\nlocal function swing(player)\n    local character, root = getLiving(player)\n    if not character then return end\n    local bat = character:FindFirstChild(tool.Name)\n    if not bat or not bat:IsA(\"Tool\") or not bat:FindFirstChild(\"PaddedHead\") then return end\n    local now = workspace:GetServerTimeNow()\n    if Rules.IsStunned(player) then return end\n    if now - (lastSwing[player] or -math.huge) < Rules.SwingCooldown then return end\n    -- Rate limit rejected attempts as well as accepted swings.\n    lastSwing[player] = now\n    if player:GetAttribute(\"CarryingSlime\") then feedback(player, \"Put down your baby before swinging.\"); return end\n    if Rules.IsSafe(character) then feedback(player, \"Bases and the collect zone are safe.\"); return end\n    animate(bat)\n    local nearest, distance\n    for _, other in ipairs(Players:GetPlayers()) do\n        if other ~= player then\n            local c, r, h = getLiving(other)\n            if c and not Rules.IsSafe(c) and (other:GetAttribute(\"BatProtectedUntil\") or 0) <= now then\n                local delta = r.Position - root.Position\n                local d = delta.Magnitude\n                -- A short forward arc, never a hit behind the attacker or through a wall.\n                if d <= Rules.Range and (d < .01 or root.CFrame.LookVector:Dot(delta.Unit) >= .15)\n                    and clearLine(root.Position, r.Position, character, c)\n                    and (not distance or d < distance) then\n                    nearest, distance = {player = other, root = r, humanoid = h}, d\n                end\n            end\n        end\n    end\n    if nearest then\n        -- Drop before stun, so capture restores the normal walking speed first.\n        nearest.player:SetAttribute(\"BatProtectedUntil\", now + Rules.HitProtection)\n        nearest.player:SetAttribute(\"BatStunnedUntil\", now + Rules.StunDuration)\n        local dropped = interrupt:Invoke(nearest.player)\n        knockback(nearest.player, nearest.root, nearest.humanoid, root)\n        feedback(player, dropped and \"Hit! Their baby is on the ground.\" or \"Hit!\")\n        feedback(nearest.player, dropped and \"Baby dropped! Equip your grabber to recover it.\" or \"Hit! You have two seconds of protection.\")\n    end\nend\nremote.OnServerEvent:Connect(function(player, action)\n    if action == \"Drop\" then\n        local character = getLiving(player)\n        if character and player:GetAttribute(\"CarryingSlime\") and not Rules.IsStunned(player) and not Rules.IsSafe(character) then\n            interrupt:Invoke(player)\n        end\n    elseif action == nil or action == \"Swing\" then\n        swing(player)\n    end\nend)\nlocal function setup(player)\n    local function characterAdded(character)\n        stuns[player] = nil\n        player:SetAttribute(\"BatStunnedUntil\", nil)\n        player:SetAttribute(\"BatProtectedUntil\", nil)\n        local backpack = player:WaitForChild(\"Backpack\")\n        if player.Character == character and not backpack:FindFirstChild(tool.Name) and not character:FindFirstChild(tool.Name) then\n            tool:Clone().Parent = backpack\n        end\n    end\n    player.CharacterAdded:Connect(characterAdded)\n    if player.Character then task.spawn(characterAdded, player.Character) end\nend\nPlayers.PlayerAdded:Connect(setup)\nPlayers.PlayerRemoving:Connect(function(player) lastSwing[player], stuns[player] = nil, nil end)\nfor _, player in ipairs(Players:GetPlayers()) do setup(player) end\nprint(\"Slime Bat ready: 0.9s swings, 2s protection, safe bases, shared dropped babies.\")\n" end
do local parent=game:GetService("StarterPlayer"):WaitForChild("StarterPlayerScripts"); local s=parent:FindFirstChild("BatInput"); if s then assert(s.ClassName=="LocalScript") else s=Instance.new("LocalScript"); s.Name="BatInput"; s.Parent=parent end; s.Source="-- StarterPlayerScripts: standard tool activation supports mouse, touch and controller.\nlocal Players = game:GetService(\"Players\")\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal ContextActionService = game:GetService(\"ContextActionService\")\nlocal player = Players.LocalPlayer\nlocal remote = ReplicatedStorage:WaitForChild(\"SlimeBatSwing\")\nlocal connected = setmetatable({}, {__mode = \"k\"})\nlocal function watch(tool)\n    if not tool:IsA(\"Tool\") or tool.Name ~= \"Slime Bat\" or connected[tool] then return end\n    connected[tool] = true\n    tool.Activated:Connect(function() remote:FireServer() end)\nend\nlocal function characterAdded(character)\n    character.ChildAdded:Connect(watch)\n    for _, tool in ipairs(character:GetChildren()) do watch(tool) end\nend\nplayer.CharacterAdded:Connect(characterAdded)\nif player.Character then characterAdded(player.Character) end\nlocal gui = Instance.new(\"ScreenGui\")\ngui.Name, gui.ResetOnSpawn = \"BatFeedback\", false\ngui.Parent = player:WaitForChild(\"PlayerGui\")\nlocal label = Instance.new(\"TextLabel\")\nlabel.AnchorPoint = Vector2.new(.5, 0)\nlabel.Position, label.Size = UDim2.new(.5,0,.18,0), UDim2.new(.8,0,0,48)\nlabel.BackgroundColor3, label.BackgroundTransparency = Color3.fromRGB(25,65,52), .1\nlabel.TextColor3, label.TextSize, label.Font = Color3.new(1,1,1), 20, Enum.Font.GothamBold\nlabel.TextWrapped, label.Visible, label.Parent = true, false, gui\nInstance.new(\"UICorner\", label).CornerRadius = UDim.new(0,10)\nlocal version = 0\nremote.OnClientEvent:Connect(function(kind, message)\n    if kind ~= \"Message\" then return end\n    version += 1\n    local current = version\n    label.Text, label.Visible, label.TextTransparency = message, true, 0\n    task.delay(2, function()\n        if current ~= version then return end\n        label.Visible = false\n    end)\nend)\n\n-- Carrying players can put a baby down before switching to their bat.\nlocal function updateDropAction()\n    ContextActionService:UnbindAction(\"DropBaby\")\n    if player:GetAttribute(\"CarryingSlime\") then\n        ContextActionService:BindAction(\"DropBaby\", function(_, state)\n            if state == Enum.UserInputState.Begin then remote:FireServer(\"Drop\") end\n            return Enum.ContextActionResult.Sink\n        end, true, Enum.KeyCode.Q, Enum.KeyCode.ButtonB)\n        ContextActionService:SetTitle(\"DropBaby\", \"Drop Baby\")\n        ContextActionService:SetPosition(\"DropBaby\", UDim2.new(1, -160, 1, -170))\n    end\nend\nplayer:GetAttributeChangedSignal(\"CarryingSlime\"):Connect(updateDropAction)\nupdateDropAction()\n" end
print("Slime Bat installed. Save locally, then start a 2-player test.")